// Generated by esquadro: do not edit. A record's page, and how a field's
// value is shown (yours too, from src/fields.ts).
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { Link, useNavigate } from "@tanstack/react-router"
import { fields as yours } from "@/fields.ts"
import { Badge } from "@/components/ui/badge.tsx"
import { Button } from "@/components/ui/button.tsx"
import { Card } from "@/components/ui/card.tsx"
import { api } from "../api.ts"
import { ask } from "./confirm.tsx"
import { describe } from "./errors.ts"
import { format, t } from "./i18n.ts"
import { resources } from "../resources.gen.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import type { Resource } from "./resource.ts"
import { toast } from "./toast.tsx"

/** A field's value: your own renderer for its name or kind, or the kit's. */
export function FieldValue({ field, record }: { field: FieldMeta; record: Rec }) {
  const value = record[field.name]
  const own = yours[field.name] ?? yours[field.kind]
  if (own?.show) return <>{own.show(value, record)}</>
  if (field.kind === "enum" && value) return <Badge>{String(value)}</Badge>
  if (field.kind === "relation" && value) {
    const related = record[field.name.replace(/_id$/, "")] as Rec | undefined
    if (related && field.display) return <>{String(related[field.display] ?? related.id)}</>
    return <RelationValue field={field} id={String(value)} />
  }
  return <>{format(field, value)}</>
}

/** A record of the resource; none without an id (a create). */
/** A related record, by the field it is shown by: fetched once, then cached. */
function RelationValue({ field, id }: { field: FieldMeta; id: string }) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const related = useQuery({
    queryKey: [target?.name ?? field.target, "get", id],
    queryFn: () => target.api(api as never).get(id),
    enabled: target !== undefined,
    staleTime: 60_000,
  })
  const shown = related.data?.[field.display ?? "id"]
  if (shown === undefined || shown === null) return <span className="text-muted-foreground">{id.slice(0, 8)}</span>
  if (target) {
    return (
      <Link to={`/${target.name}/${id}` as never} className="underline" onClick={(e) => e.stopPropagation()}>
        {String(shown)}
      </Link>
    )
  }
  return <>{String(shown)}</>
}

export function useRecord(resource: Resource, id: string | undefined) {
  return useQuery({
    queryKey: [resource.meta.name, "get", id],
    queryFn: () => resource.meta.api(api as never).get(id ?? ""),
    enabled: id !== undefined,
  })
}

export function ResourceShow({ resource, id }: { resource: Resource; id: string }) {
  const { meta } = resource
  const record = useRecord(resource, id)
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const remove = useMutation({
    mutationFn: (r: Rec) => meta.api(api as never).delete(r.id, { ifMatch: r }),
    onSuccess: () => {
      toast(t("deleted"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      navigate({ to: `/${meta.name}` as never })
    },
    onError: (e) => toast(describe(e), "error"),
  })
  if (record.isPending) return <div className="h-32 animate-pulse rounded-lg bg-muted" />
  if (record.isError) return <p className="text-destructive">{describe(record.error)}</p>
  const r = record.data
  const can = r.can ?? []
  const title = resource.title ? String(r[resource.title.name] ?? "") : meta.singular
  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center gap-2">
        <h1 className="mr-auto text-xl font-semibold">{title}</h1>
        {resource.actions?.filter((a) => !a.when || a.when(r)).map((a) => (
          <Button
            key={a.label}
            variant="outline"
            onClick={async () => {
              if (a.confirm && !(await ask(a.confirm))) return
              try {
                await a.run(r)
                toast(t("done"))
                queryClient.invalidateQueries({ queryKey: [meta.name] })
              } catch (e) {
                toast(describe(e), "error")
              }
            }}
          >
            {a.label}
          </Button>
        ))}
        {can.includes("update") && (
          <Button variant="outline" asLink>
            <Link to={`/${meta.name}/${r.id}/edit` as never}>{t("edit")}</Link>
          </Button>
        )}
        {can.includes("delete") && (
          <Button
            variant="destructive"
            disabled={remove.isPending}
            onClick={async () => (await ask(t("confirmDelete"))) && remove.mutate(r)}
          >
            {t("delete")}
          </Button>
        )}
      </div>
      <Card>
        <dl className="grid gap-4 sm:grid-cols-2">
          {(resource.show ?? resource.form).map((f) => (
            <div key={f.name}>
              <dt className="text-sm text-muted-foreground">{f.label}</dt>
              <dd>
                <FieldValue field={f} record={r} />
              </dd>
            </div>
          ))}
        </dl>
      </Card>
    </div>
  )
}
